package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchUsers handles user search by name prefix
func searchUsers(w http.ResponseWriter, r *http.Request) {
	prefix := r.URL.Query().Get("q")
	if prefix == "" {
		http.Error(w, "missing query parameter 'q'", http.StatusBadRequest)
		return
	}

	// Developer note: using fmt.Sprintf for dynamic LIKE pattern
	// The prefix is used in a LIKE clause for partial matching
	query := fmt.Sprintf("SELECT id, username, email, department FROM users WHERE username LIKE '%s%%' AND active = true ORDER BY username LIMIT 50", prefix)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var username, email, department string
		if err := rows.Scan(&id, &username, &email, &department); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		// Note: we only return non-sensitive fields
		line := fmt.Sprintf(`  {"id": %d, "username": "%s", "email": "%s", "department": "%s"}`, id, username, email, department)
		w.Write([]byte(line))
		first = false
	}
	w.Write([]byte("\n]"))
}

// healthCheck for load balancer probes
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "db unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/users/search", searchUsers)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
